import{_ as t,C as r,o as d,c as s,j as a,a as i,E as c,a5 as n}from"./chunks/framework.B1qnvv14.js";const q=JSON.parse('{"title":"Por que o automacli","description":"","frontmatter":{"title":"Por que o automacli"},"headers":[],"relativePath":"por-que.md","filePath":"por-que.md","lastUpdated":1792102410000}'),m={name:"por-que.md"};function u(l,o,p,h,g,b){const e=r("CopyOrDownloadAsMarkdownButtons");return d(),s("div",null,[o[0]||(o[0]=a("h1",{id:"por-que-o-automacli",tabindex:"-1"},[i("Por que o automacli? "),a("a",{class:"header-anchor",href:"#por-que-o-automacli","aria-label":'Permalink to "Por que o automacli?"'},"​")],-1)),c(e),o[1]||(o[1]=n('<p>Quem precisa de várias branches no ar ao mesmo tempo costuma chegar em uma destas três respostas: um checkout só com scripts à mão, <code>git worktree</code>, ou uma ferramenta que cuide do ambiente inteiro. As duas primeiras resolvem a parte do <strong>código</strong>. O problema de verdade está no que fica em volta do código: dependências instaladas, portas publicadas, bancos com dados, arquivos que o git não versiona e o custo de limpar tudo depois.</p><p>É esse &quot;em volta&quot; que o automacli automatiza.</p><h2 id="o-que-uma-branch-precisa-para-rodar" tabindex="-1">O que uma branch precisa para rodar <a class="header-anchor" href="#o-que-uma-branch-precisa-para-rodar" aria-label="Permalink to &quot;O que uma branch precisa para rodar&quot;">​</a></h2><p>Uma branch de um projeto com Docker não é só a árvore de arquivos. Para ela subir, é preciso:</p><table tabindex="0"><thead><tr><th>Peça</th><th>Exemplo</th><th>De onde vem</th></tr></thead><tbody><tr><td><strong>Código</strong></td><td>a branch <code>feat/pagamentos</code></td><td>git</td></tr><tr><td><strong>Dependências</strong></td><td><code>node_modules</code>, <code>vendor</code>, <code>.venv</code></td><td><code>pnpm install</code>, <code>composer install</code>, <code>pip install</code></td></tr><tr><td><strong>Portas livres</strong></td><td><code>3000</code>, <code>4000</code>, <code>8080</code></td><td>ninguém mais pode estar usando</td></tr><tr><td><strong>Serviços com estado</strong></td><td>Postgres, Redis, OpenSearch, SQS</td><td>um compose, volumes, seeds</td></tr><tr><td><strong>Arquivos não versionados</strong></td><td><code>.env</code>, scripts pessoais, instruções do agente</td><td>você, de novo, em cada cópia</td></tr><tr><td><strong>Limpeza</strong></td><td>parar containers, apagar volumes, remover o diretório</td><td>você, quando lembrar</td></tr></tbody></table><p>Cada abordagem abaixo cobre uma fatia diferente dessa tabela.</p><h2 id="um-checkout-e-scripts-manuais" tabindex="-1">Um checkout e scripts manuais <a class="header-anchor" href="#um-checkout-e-scripts-manuais" aria-label="Permalink to &quot;Um checkout e scripts manuais&quot;">​</a></h2><p>É o ponto de partida de quase todo time: um clone, <code>git checkout</code> para trocar de branch e, com o tempo, um <code>clone-task.sh</code> que copia o repositório e troca as portas com <code>sed</code>.</p><p>O que funciona:</p><ul><li>Não exige nada além de git e do próprio compose.</li><li>Um script simples resolve o primeiro caso de uso em uma tarde.</li></ul><p>Onde quebra:</p><ul><li><strong>Portas na mão.</strong> O script precisa saber todas as portas publicadas pela stack e escolher um deslocamento que não colida com nenhuma outra cópia. Com <code>extends</code>, <code>include</code> e variáveis no compose, a lista muda sem avisar. O automacli lê as portas com <code>docker compose config</code> e reserva um <a href="./como-funciona#_2-slot">slot</a> livre, pulando os que colidiriam com outra task (<a href="./solucao-de-problemas#port-is-already-allocated-ao-subir-a-stack">port is already allocated</a>).</li><li><strong>Edita o que é do repositório.</strong> Trocar portas com <code>sed</code> nos arquivos compose e no <code>.env</code> suja o <code>git status</code> e vira conflito no próximo rebase. O automacli gera um <a href="./como-funciona#_4-override">override</a> ao lado e o esconde em <code>.git/info/exclude</code>.</li><li><strong>Uma instalação por cópia.</strong> Cada clone novo repete <code>pnpm install</code>, <code>composer install</code> e o download de imagens. O automacli copia a task a partir do repo base por <a href="./requisitos">snapshot ou reflink</a>: segundos, com <code>node_modules</code> e <code>vendor</code> já no lugar e sem gastar disco até os arquivos divergirem.</li><li><strong>Um banco por cópia, ou um banco brigando com o outro.</strong> Ou cada cópia sobe o seu Postgres (e cada um precisa de porta, volume e seed), ou todas apontam para o mesmo e a primeira a dar <code>docker compose down</code> derruba o das outras. Os <a href="./como-funciona#_5-servicos-compartilhados">serviços compartilhados</a> rodam uma vez, a partir do repo base, e, no modo padrão, nenhuma task consegue derrubá-los.</li><li><strong>O script é de uma pessoa.</strong> Ele conhece um repositório, uma máquina e um jeito de trabalhar. Quando alguém novo entra, recebe o script por mensagem e descobre as pegadinhas sozinho. No automacli o que varia entre projetos fica em um <a href="./perfil">perfil YAML</a> versionável; o resto é descoberto.</li><li><strong>Ninguém sabe o que está no ar.</strong> Sem um lugar que liste as cópias, os slots e o consumo de cada uma, a máquina acumula stacks esquecidas. O <a href="./monitor">monitor</a> mostra cada task com o estado do PR, CPU, memória e disco real, e <code>automacli branches</code> remove uma task derrubando a stack dela antes.</li></ul><h2 id="git-worktree" tabindex="-1">git worktree <a class="header-anchor" href="#git-worktree" aria-label="Permalink to &quot;git worktree&quot;">​</a></h2><p><code>git worktree add ../feat-pagamentos feat/pagamentos</code> cria um segundo diretório de trabalho ligado ao mesmo <code>.git</code>. É a resposta certa para a pergunta &quot;como ter duas branches abertas ao mesmo tempo&quot;, e o automacli não tenta substituí-la nesse ponto.</p><p>O que funciona:</p><ul><li>Faz parte do git, sem instalar nada.</li><li>A segunda árvore nasce em segundos e compartilha objetos, refs e stashes com a primeira.</li><li>Perfeito para olhar um PR, fazer um cherry-pick ou comparar dois estados do código.</li></ul><p>Onde para:</p><ul><li><strong>Só o código vem junto.</strong> <code>node_modules</code>, <code>vendor</code> e <code>.venv</code> não são versionados, então cada worktree começa vazia e precisa de um install. Com pnpm e o store quente ele é barato em disco (hard links) e leva o tempo de linkar os arquivos; com Composer, pip, npm ou yarn clássico é uma cópia inteira dos pacotes. A task do automacli nasce de um snapshot do repo base: as dependências já estão lá, em blocos compartilhados.</li><li><strong>Portas continuam fixas.</strong> O compose de cada worktree publica as mesmas portas; a segunda stack falha com <code>port is already allocated</code>. Resolver isso é voltar aos scripts manuais do item anterior.</li><li><strong>Um banco por worktree, ou um banco brigando com o outro.</strong> Cada worktree é um projeto compose com seus volumes, então ou cada uma sobe o seu Postgres, ou todas apontam para o mesmo e qualquer <code>docker compose down</code> derruba o das outras. O automacli roda os serviços com estado uma vez, a partir do repo base, fora da stack de cada task.</li><li><strong>Arquivos não versionados ficam para trás.</strong> O <code>.env</code>, o <code>CLAUDE.local.md</code> e o script que você usa todo dia não acompanham a worktree. Os <a href="./instalacao#estrutura-do-diretorio-de-configuracao">templates</a> do automacli entram em toda task no mesmo caminho, automaticamente.</li></ul><p>O que o automacli faz a mais, sem que isso seja falha do worktree, que nunca se propôs a cuidar de ambiente: slot e override gerados, <a href="./isolamento">isolamento</a> por slice systemd com teto de memória, e o <a href="./monitor">monitor</a> registrando o que está no ar e quem foi morto por falta de memória. Nos dois casos vale uma branch por vez: o git recusa a mesma branch em duas worktrees, e o automacli cria um diretório por branch.</p><p>Se o seu projeto não tem Docker e as dependências instalam em segundos, <code>git worktree</code> basta. O automacli entra quando a stack em volta do código pesa mais do que o código.</p><h2 id="lado-a-lado" tabindex="-1">Lado a lado <a class="header-anchor" href="#lado-a-lado" aria-label="Permalink to &quot;Lado a lado&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Checkout + scripts</th><th><code>git worktree</code></th><th>automacli</th></tr></thead><tbody><tr><td>Diretório por branch</td><td>o script copia</td><td>sim</td><td>sim, task por branch</td></tr><tr><td>Tempo até a branch rodar</td><td>clone + install</td><td>install</td><td>segundos (snapshot ou reflink)</td></tr><tr><td>Dependências instaladas</td><td>de novo em cada cópia</td><td>de novo em cada worktree</td><td>vêm do repo base</td></tr><tr><td>Disco por branch</td><td>uma cópia inteira</td><td>só o código, mais o install</td><td>só o que a branch muda</td></tr><tr><td>Portas</td><td>calculadas no script</td><td>colidem</td><td>slot por task, override gerado</td></tr><tr><td>Arquivos do repositório</td><td>editados com <code>sed</code></td><td>intactos</td><td>intactos, override fora do git</td></tr><tr><td>Banco, cache e busca</td><td>um por cópia, ou briga</td><td>um por worktree</td><td>uma instância, compartilhada e protegida</td></tr><tr><td><code>.env</code> e arquivos pessoais</td><td>copiar à mão</td><td>copiar à mão</td><td>templates em toda task</td></tr><tr><td>Limite de memória</td><td>não</td><td>não</td><td>slice systemd por slot</td></tr><tr><td>Visibilidade do que está no ar</td><td><code>docker ps</code></td><td><code>git worktree list</code></td><td>monitor HTTP e MCP</td></tr><tr><td>Limpeza</td><td>à mão</td><td><code>git worktree remove</code></td><td><code>branches</code> para a stack e apaga a task</td></tr><tr><td>Configuração por projeto</td><td>um script por repositório</td><td>nenhuma</td><td>um perfil YAML, descoberto quando falta</td></tr></tbody></table><h2 id="quando-nao-vale-a-pena" tabindex="-1">Quando não vale a pena <a class="header-anchor" href="#quando-nao-vale-a-pena" aria-label="Permalink to &quot;Quando não vale a pena&quot;">​</a></h2><ul><li>O repositório não tem stack Docker e as dependências instalam em segundos: <code>git worktree</code> resolve.</li><li>Você trabalha sempre em uma branch por vez e troca pouco: um checkout basta.</li><li>O disco das tasks não suporta reflink nem btrfs: o automacli continua funcionando, caindo para <code>git clone --reference</code> (e, sem repo base, <code>git clone</code>), mas a vantagem de tempo e disco diminui. Veja o que a sua máquina tem com <code>automacli doctor</code> em <a href="./requisitos">Requisitos e ambiente</a>.</li></ul><h2 id="para-seguir" tabindex="-1">Para seguir <a class="header-anchor" href="#para-seguir" aria-label="Permalink to &quot;Para seguir&quot;">​</a></h2><ul><li><a href="./como-funciona">Como funciona</a>: slots, portas, override e serviços compartilhados em detalhe.</li><li><a href="./instalacao">Instalação</a>: o executável pronto e os pacotes por distribuição.</li><li><a href="./exemplos">Exemplos</a>: perfis prontos para copiar.</li></ul>',26))])}const k=t(m,[["render",u]]);export{q as __pageData,k as default};
